function minimumEffortPath(heights){const R=heights.length,C=heights[0].length;const dist=Array.from({length:R},()=>new Array(C).fill(Infinity));dist[0][0]=0;const h=new Heap((a,b)=>a[0]-b[0]);h.push([0,0,0]);while(h.size){const [d,r,c]=h.pop();if(d>dist[r][c])continue;if(r===R-1&&c===C-1)return d;for(const [x,y] of [[r+1,c],[r-1,c],[r,c+1],[r,c-1]]){if(x<0||y<0||x>=R||y>=C)continue;const nd=Math.max(d,Math.abs(heights[x][y]-heights[r][c]));if(nd<dist[x][y]){dist[x][y]=nd;h.push([nd,x,y]);}}}return 0;}

function runNumArray(ops, args) {
  let prefix = [0];
  const out = [];
  for (let i = 0; i < ops.length; i++) {
    if (ops[i] === "NumArray") {
      prefix = [0];
      for (const x of args[i][0]) prefix.push(prefix[prefix.length - 1] + x);
      out.push(null);
    } else {
      const [left, right] = args[i];
      out.push(prefix[right + 1] - prefix[left]);
    }
  }
  return out;
}

function productExceptSelf(nums) {
  const n = nums.length;
  const res = new Array(n).fill(1);
  let left = 1;
  for (let i = 0; i < n; i++) {
    res[i] = left;
    left *= nums[i];
  }
  let right = 1;
  for (let i = n - 1; i >= 0; i--) {
    res[i] *= right;
    right *= nums[i];
  }
  return res;
}

function findMaxLength(nums) {
  const firstSeen = new Map([[0, -1]]);
  let balance = 0, best = 0;
  for (let i = 0; i < nums.length; i++) {
    balance += nums[i] === 1 ? 1 : -1;
    if (firstSeen.has(balance)) best = Math.max(best, i - firstSeen.get(balance));
    else firstSeen.set(balance, i);
  }
  return best;
}

function pivotIndex(nums) {
  const total = nums.reduce((a, b) => a + b, 0);
  let left = 0;
  for (let i = 0; i < nums.length; i++) {
    if (left === total - left - nums[i]) return i;
    left += nums[i];
  }
  return -1;
}

function spiralOrder(matrix) {
  const res = [];
  let top = 0, bottom = matrix.length - 1;
  let left = 0, right = matrix[0].length - 1;
  while (top <= bottom && left <= right) {
    for (let c = left; c <= right; c++) res.push(matrix[top][c]);
    top++;
    for (let r = top; r <= bottom; r++) res.push(matrix[r][right]);
    right--;
    if (top <= bottom) {
      for (let c = right; c >= left; c--) res.push(matrix[bottom][c]);
      bottom--;
    }
    if (left <= right) {
      for (let r = bottom; r >= top; r--) res.push(matrix[r][left]);
      left++;
    }
  }
  return res;
}

function rotate(matrix) {
  const n = matrix.length;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      [matrix[i][j], matrix[j][i]] = [matrix[j][i], matrix[i][j]];
    }
  }
  for (const row of matrix) row.reverse();
  return matrix;
}

function setZeroes(matrix) {
  const m = matrix.length, n = matrix[0].length;
  const rows = new Set(), cols = new Set();
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (matrix[i][j] === 0) { rows.add(i); cols.add(j); }
    }
  }
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (rows.has(i) || cols.has(j)) matrix[i][j] = 0;
    }
  }
  return matrix;
}

function gameOfLife(board) {
  const m = board.length, n = board[0].length;
  // bit 0 = current state, bit 1 = next state
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      let live = 0;
      for (let di = -1; di <= 1; di++) {
        for (let dj = -1; dj <= 1; dj++) {
          if (di === 0 && dj === 0) continue;
          const r = i + di, c = j + dj;
          if (r >= 0 && r < m && c >= 0 && c < n) live += board[r][c] & 1;
        }
      }
      const alive = board[i][j] & 1;
      if (alive ? (live === 2 || live === 3) : live === 3) board[i][j] |= 2;
    }
  }
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) board[i][j] >>= 1;
  }
  return board;
}

function updateMatrix(mat) {
  const m = mat.length, n = mat[0].length;
  const dist = mat.map(row => row.map(v => (v === 0 ? 0 : -1)));
  let queue = [];
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) if (mat[i][j] === 0) queue.push([i, j]);
  }
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let head = 0;
  while (head < queue.length) {
    const [r, c] = queue[head++];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < m && nc >= 0 && nc < n && dist[nr][nc] === -1) {
        dist[nr][nc] = dist[r][c] + 1;
        queue.push([nr, nc]);
      }
    }
  }
  return dist;
}

