solution:
function numBusesToDestination(routes, source, target) {
  if (source === target) return 0;
  const routesAtStop = new Map();
  routes.forEach((stops, bus) => {
    for (const s of stops) {
      if (!routesAtStop.has(s)) routesAtStop.set(s, []);
      routesAtStop.get(s).push(bus);
    }
  });
  const seenBus = new Set(), seenStop = new Set([source]);
  let level = [source], buses = 0;
  while (level.length) {
    buses++;
    const next = [];
    for (const stop of level) {
      for (const bus of routesAtStop.get(stop) || []) {
        if (seenBus.has(bus)) continue;
        seenBus.add(bus);
        for (const s of routes[bus]) {
          if (s === target) return buses;
          if (!seenStop.has(s)) { seenStop.add(s); next.push(s); }
        }
      }
    }
    level = next;
  }
  return -1;
}

function openLock(deadends, target) {
  const dead = new Set(deadends);
  if (dead.has("0000")) return -1;
  if (target === "0000") return 0;
  const seen = new Set(["0000"]);
  let level = ["0000"], steps = 0;
  while (level.length) {
    steps++;
    const next = [];
    for (const cur of level) {
      for (let i = 0; i < 4; i++) {
        const d = Number(cur[i]);
        for (const delta of [1, 9]) {
          const nxt = cur.slice(0, i) + ((d + delta) % 10) + cur.slice(i + 1);
          if (dead.has(nxt) || seen.has(nxt)) continue;
          if (nxt === target) return steps;
          seen.add(nxt);
          next.push(nxt);
        }
      }
    }
    level = next;
  }
  return -1;
}

function shortestPathBinaryMatrix(grid) {
  const n = grid.length;
  if (grid[0][0] === 1 || grid[n - 1][n - 1] === 1) return -1;
  const seen = grid.map(row => row.map(() => false));
  seen[0][0] = true;
  let level = [[0, 0]], length = 1;
  while (level.length) {
    const next = [];
    for (const [r, c] of level) {
      if (r === n - 1 && c === n - 1) return length;
      for (let dr = -1; dr <= 1; dr++) {
        for (let dc = -1; dc <= 1; dc++) {
          const nr = r + dr, nc = c + dc;
          if (nr < 0 || nc < 0 || nr >= n || nc >= n) continue;
          if (grid[nr][nc] === 1 || seen[nr][nc]) continue;
          seen[nr][nc] = true;
          next.push([nr, nc]);
        }
      }
    }
    level = next;
    length++;
  }
  return -1;
}

function splitArray(nums, k) {
  let lo = Math.max(...nums), hi = nums.reduce((a, b) => a + b, 0);
  const pieces = limit => {
    let count = 1, sum = 0;
    for (const x of nums) {
      if (sum + x > limit) { count++; sum = 0; }
      sum += x;
    }
    return count;
  };
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (pieces(mid) <= k) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

function shipWithinDays(weights, days) {
  let lo = Math.max(...weights), hi = weights.reduce((a, b) => a + b, 0);
  const daysNeeded = capacity => {
    let d = 1, load = 0;
    for (const w of weights) {
      if (load + w > capacity) { d++; load = 0; }
      load += w;
    }
    return d;
  };
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (daysNeeded(mid) <= days) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

function kthSmallest(matrix, k) {
  const n = matrix.length;
  // number of cells with value <= x, walking from the bottom-left corner
  const countAtMost = x => {
    let count = 0, r = n - 1, c = 0;
    while (r >= 0 && c < n) {
      if (matrix[r][c] <= x) { count += r + 1; c++; }
      else r--;
    }
    return count;
  };
  let lo = matrix[0][0], hi = matrix[n - 1][n - 1];
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (countAtMost(mid) >= k) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

function buildTree(arr) {
  if (!arr.length || arr[0] === null) return null;
  const root = { val: arr[0], left: null, right: null };
  const queue = [root];
  let i = 1;
  while (queue.length && i < arr.length) {
    const node = queue.shift();
    if (i < arr.length && arr[i] !== null) {
      node.left = { val: arr[i], left: null, right: null };
      queue.push(node.left);
    }
    i++;
    if (i < arr.length && arr[i] !== null) {
      node.right = { val: arr[i], left: null, right: null };
      queue.push(node.right);
    }
    i++;
  }
  return root;
}

function diameterOfBinaryTree(root) {
  const tree = buildTree(root);
  let best = 0;
  function depth(node) {
    if (!node) return 0;
    const l = depth(node.left), r = depth(node.right);
    best = Math.max(best, l + r); // longest path that bends at this node
    return 1 + Math.max(l, r);
  }
  depth(tree);
  return best;
}

function buildTree(arr) {
  if (!arr.length || arr[0] === null) return null;
  const root = { val: arr[0], left: null, right: null };
  const queue = [root];
  let i = 1;
  while (queue.length && i < arr.length) {
    const node = queue.shift();
    if (i < arr.length && arr[i] !== null) {
      node.left = { val: arr[i], left: null, right: null };
      queue.push(node.left);
    }
    i++;
    if (i < arr.length && arr[i] !== null) {
      node.right = { val: arr[i], left: null, right: null };
      queue.push(node.right);
    }
    i++;
  }
  return root;
}

function pathSum(root, targetSum) {
  const tree = buildTree(root);
  const result = [], path = [];
  function dfs(node, remaining) {
    if (!node) return;
    path.push(node.val);
    remaining -= node.val;
    if (!node.left && !node.right && remaining === 0) result.push([...path]);
    dfs(node.left, remaining);
    dfs(node.right, remaining);
    path.pop();
  }
  dfs(tree, targetSum);
  return result;
}

function buildTree(arr) {
  if (!arr.length || arr[0] === null) return null;
  const root = { val: arr[0], left: null, right: null };
  const queue = [root];
  let i = 1;
  while (queue.length && i < arr.length) {
    const node = queue.shift();
    if (i < arr.length && arr[i] !== null) {
      node.left = { val: arr[i], left: null, right: null };
      queue.push(node.left);
    }
    i++;
    if (i < arr.length && arr[i] !== null) {
      node.right = { val: arr[i], left: null, right: null };
      queue.push(node.right);
    }
    i++;
  }
  return root;
}

function longestUnivaluePath(root) {
  const tree = buildTree(root);
  let best = 0;
  // returns the longest downward same-value chain (in edges) starting at node
  function chain(node) {
    if (!node) return 0;
    const l = chain(node.left), r = chain(node.right);
    const left = node.left && node.left.val === node.val ? l + 1 : 0;
    const right = node.right && node.right.val === node.val ? r + 1 : 0;
    best = Math.max(best, left + right);
    return Math.max(left, right);
  }
  chain(tree);
  return best;
}

function buildTree(arr) {
  if (!arr.length || arr[0] === null) return null;
  const root = { val: arr[0], left: null, right: null };
  const queue = [root];
  let i = 1;
  while (queue.length && i < arr.length) {
    const node = queue.shift();
    if (i < arr.length && arr[i] !== null) {
      node.left = { val: arr[i], left: null, right: null };
      queue.push(node.left);
    }
    i++;
    if (i < arr.length && arr[i] !== null) {
      node.right = { val: arr[i], left: null, right: null };
      queue.push(node.right);
    }
    i++;
  }
  return root;
}

function findTilt(root) {
  const tree = buildTree(root);
  let total = 0;
  function sum(node) {
    if (!node) return 0;
    const l = sum(node.left), r = sum(node.right);
    total += Math.abs(l - r);
    return l + r + node.val;
  }
  sum(tree);
  return total;
}

function cloneGraph(adjList) {
  if (adjList.length === 0) return [];
  // build the original graph: node i+1 has neighbours adjList[i]
  const nodes = adjList.map((_, i) => ({ val: i + 1, neighbors: [] }));
  adjList.forEach((nbrs, i) => { nodes[i].neighbors = nbrs.map(v => nodes[v - 1]); });
  // deep copy with DFS and a map original -> copy
  const copies = new Map();
  function clone(node) {
    if (copies.has(node)) return copies.get(node);
    const copy = { val: node.val, neighbors: [] };
    copies.set(node, copy);
    for (const nb of node.neighbors) copy.neighbors.push(clone(nb));
    return copy;
  }
  const start = clone(nodes[0]);
  // read the copy back as an adjacency list
  const out = [], seen = new Set([start]), stack = [start];
  while (stack.length) {
    const node = stack.pop();
    out[node.val - 1] = node.neighbors.map(x => x.val);
    for (const nb of node.neighbors) {
      if (!seen.has(nb)) { seen.add(nb); stack.push(nb); }
    }
  }
  return out;
}

function solve(board) {
  const m = board.length, n = board[0].length;
  const stack = [];
  const push = (r, c) => {
    if (r >= 0 && r < m && c >= 0 && c < n && board[r][c] === "O") {
      board[r][c] = "S"; // safe: connected to the border
      stack.push([r, c]);
    }
  };
  for (let i = 0; i < m; i++) { push(i, 0); push(i, n - 1); }
  for (let j = 0; j < n; j++) { push(0, j); push(m - 1, j); }
  while (stack.length) {
    const [r, c] = stack.pop();
    push(r + 1, c); push(r - 1, c); push(r, c + 1); push(r, c - 1);
  }
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (board[i][j] === "O") board[i][j] = "X";
      else if (board[i][j] === "S") board[i][j] = "O";
    }
  }
  return board;
}

