solution:
function floodFill(image, sr, sc, color) {
  const original = image[sr][sc];
  if (original === color) return image;
  const stack = [[sr, sc]];
  image[sr][sc] = color;
  while (stack.length) {
    const [r, c] = stack.pop();
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < image.length && nc >= 0 && nc < image[0].length && image[nr][nc] === original) {
        image[nr][nc] = color;
        stack.push([nr, nc]);
      }
    }
  }
  return image;
}

function decodeString(s) {
  const counts = [], prefixes = [];
  let current = "", num = 0;
  for (const ch of s) {
    if (ch >= "0" && ch <= "9") {
      num = num * 10 + Number(ch);
    } else if (ch === "[") {
      counts.push(num);
      prefixes.push(current);
      num = 0;
      current = "";
    } else if (ch === "]") {
      const times = counts.pop();
      current = prefixes.pop() + current.repeat(times);
    } else {
      current += ch;
    }
  }
  return current;
}

function longestValidParentheses(s) {
  const stack = [-1]; // index just before the current valid stretch
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "(") {
      stack.push(i);
    } else {
      stack.pop();
      if (stack.length === 0) stack.push(i);
      else best = Math.max(best, i - stack[stack.length - 1]);
    }
  }
  return best;
}

function asteroidCollision(asteroids) {
  const stack = [];
  for (const a of asteroids) {
    let alive = true;
    while (alive && a < 0 && stack.length && stack[stack.length - 1] > 0) {
      const top = stack[stack.length - 1];
      if (top < -a) {
        stack.pop(); // the right-moving one is smaller and explodes
      } else {
        if (top === -a) stack.pop(); // both explode
        alive = false;
      }
    }
    if (alive) stack.push(a);
  }
  return stack;
}

function numDecodings(s) {
  const n = s.length;
  const ways = new Array(n + 1).fill(0); // ways[i] = decodings of the first i chars
  ways[0] = 1;
  for (let i = 1; i <= n; i++) {
    if (s[i - 1] !== "0") ways[i] += ways[i - 1];
    if (i >= 2) {
      const two = Number(s.slice(i - 2, i));
      if (two >= 10 && two <= 26) ways[i] += ways[i - 2];
    }
  }
  return ways[n];
}

