}

solution:
function jobScheduling(startTime, endTime, profit) {
  const jobs = startTime.map((s, i) => [s, endTime[i], profit[i]]).sort((a, b) => a[1] - b[1]);
  const ends = [];
  const best = [0]; // best[i] = max profit using the first i jobs (by end time)
  for (const [s, e, p] of jobs) {
    // count how many earlier jobs end at or before s
    let lo = 0, hi = ends.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (ends[mid] <= s) lo = mid + 1;
      else hi = mid;
    }
    best.push(Math.max(best[best.length - 1], best[lo] + p));
    ends.push(e);
  }
  return best[best.length - 1];
}

function countBits(n) {
  const ans = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) ans[i] = ans[i >> 1] + (i & 1);
  return ans;
}

function maxProfit(prices) {
  let hold = -Infinity; // best profit while holding a share
  let sold = 0;         // best profit on a day we just sold
  let rest = 0;         // best profit while holding nothing and free to buy
  for (const p of prices) {
    const prevSold = sold;
    sold = hold + p;
    hold = Math.max(hold, rest - p);
    rest = Math.max(rest, prevSold);
  }
  return Math.max(sold, rest);
}

function kClosest(points, k) {
  const heap = []; // max-heap of [distance, point], holds the k closest so far
  const swap = (a, b) => { [heap[a], heap[b]] = [heap[b], heap[a]]; };
  const up = i => {
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] >= heap[i][0]) break;
      swap(parent, i);
      i = parent;
    }
  };
  const down = i => {
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let big = i;
      if (l < heap.length && heap[l][0] > heap[big][0]) big = l;
      if (r < heap.length && heap[r][0] > heap[big][0]) big = r;
      if (big === i) break;
      swap(big, i);
      i = big;
    }
  };
  for (const p of points) {
    const d = p[0] * p[0] + p[1] * p[1];
    if (heap.length < k) {
      heap.push([d, p]);
      up(heap.length - 1);
    } else if (d < heap[0][0]) {
      heap[0] = [d, p];
      down(0);
    }
  }
  return heap.map(entry => entry[1]);
}

