solution:
function findClosestElements(arr, k, x) {
  // binary search for the start of the length-k window
  let lo = 0, hi = arr.length - k;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (x - arr[mid] > arr[mid + k] - x) lo = mid + 1;
    else hi = mid;
  }
  return arr.slice(lo, lo + k);
}

function leastInterval(tasks, n) {
  const freq = new Map();
  for (const t of tasks) freq.set(t, (freq.get(t) || 0) + 1);
  const maxFreq = Math.max(...freq.values());
  let countMax = 0;
  for (const f of freq.values()) if (f === maxFreq) countMax++;
  // (maxFreq - 1) full frames of size n + 1, plus the last row of the most frequent tasks
  return Math.max(tasks.length, (maxFreq - 1) * (n + 1) + countMax);
}

function generateParenthesis(n) {
  const res = [];
  function build(cur, open, close) {
    if (cur.length === 2 * n) { res.push(cur); return; }
    if (open < n) build(cur + "(", open + 1, close);
    if (close < open) build(cur + ")", open, close + 1);
  }
  build("", 0, 0);
  return res;
}

function partition(s) {
  const res = [], cur = [];
  const isPal = (l, r) => {
    while (l < r) if (s[l++] !== s[r--]) return false;
    return true;
  };
  function dfs(start) {
    if (start === s.length) { res.push([...cur]); return; }
    for (let end = start; end < s.length; end++) {
      if (!isPal(start, end)) continue;
      cur.push(s.slice(start, end + 1));
      dfs(end + 1);
      cur.pop();
    }
  }
  dfs(0);
  return res;
}

function letterCombinations(digits) {
  if (digits.length === 0) return [];
  const letters = { 2: "abc", 3: "def", 4: "ghi", 5: "jkl", 6: "mno", 7: "pqrs", 8: "tuv", 9: "wxyz" };
  const res = [];
  function build(i, cur) {
    if (i === digits.length) { res.push(cur); return; }
    for (const ch of letters[digits[i]]) build(i + 1, cur + ch);
  }
  build(0, "");
  return res;
}

function maxScore(cardPoints, k) {
  const n = cardPoints.length, w = n - k; // the cards we leave form a window of size w
  let sum = 0, total = 0;
  for (let i = 0; i < n; i++) total += cardPoints[i];
  for (let i = 0; i < w; i++) sum += cardPoints[i];
  let minWindow = sum;
  for (let i = w; i < n; i++) {
    sum += cardPoints[i] - cardPoints[i - w];
    minWindow = Math.min(minWindow, sum);
  }
  return total - minWindow;
}

function maximumSubarraySum(nums, k) {
  const count = new Map();
  let sum = 0, best = 0;
  for (let i = 0; i < nums.length; i++) {
    sum += nums[i];
    count.set(nums[i], (count.get(nums[i]) || 0) + 1);
    if (i >= k) {
      const out = nums[i - k];
      sum -= out;
      const c = count.get(out) - 1;
      if (c === 0) count.delete(out);
      else count.set(out, c);
    }
    if (i >= k - 1 && count.size === k) best = Math.max(best, sum);
  }
  return best;
}

function findMaxAverage(nums, k) {
  let sum = 0;
  for (let i = 0; i < k; i++) sum += nums[i];
  let best = sum;
  for (let i = k; i < nums.length; i++) {
    sum += nums[i] - nums[i - k];
    best = Math.max(best, sum);
  }
  return best / k;
}

function moveZeroes(nums) {
  let write = 0;
  for (let read = 0; read < nums.length; read++) {
    if (nums[read] !== 0) {
      [nums[write], nums[read]] = [nums[read], nums[write]];
      write++;
    }
  }
  return nums;
}

function triangleNumber(nums) {
  const a = [...nums].sort((x, y) => x - y);
  let count = 0;
  for (let c = a.length - 1; c >= 2; c--) {
    let l = 0, r = c - 1;
    while (l < r) {
      if (a[l] + a[r] > a[c]) { count += r - l; r--; }
      else l++;
    }
  }
  return count;
}

function twoSum(numbers, target) {
  let l = 0, r = numbers.length - 1;
  while (l < r) {
    const sum = numbers[l] + numbers[r];
    if (sum === target) return [l + 1, r + 1];
    if (sum < target) l++;
    else r--;
  }
  return [];
}

