solution:
function findTheCity(n, edges, distanceThreshold) {
  const dist = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 0 : Infinity)));
  for (const [a, b, w] of edges) {
    dist[a][b] = Math.min(dist[a][b], w);
    dist[b][a] = Math.min(dist[b][a], w);
  }
  for (let k = 0; k < n; k++) {
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];
      }
    }
  }
  let answer = -1, fewest = Infinity;
  for (let i = 0; i < n; i++) {
    let reachable = 0;
    for (let j = 0; j < n; j++) if (i !== j && dist[i][j] <= distanceThreshold) reachable++;
    if (reachable <= fewest) { fewest = reachable; answer = i; } // <= keeps the larger index on ties
  }
  return answer;
}

