solution:
function calcEquation(equations, values, queries) {
  const id = new Map();
  for (const [a, b] of equations) {
    if (!id.has(a)) id.set(a, id.size);
    if (!id.has(b)) id.set(b, id.size);
  }
  const n = id.size;
  // ratio[i][j] = i / j, or -1 when unknown
  const ratio = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : -1)));
  equations.forEach(([a, b], idx) => {
    ratio[id.get(a)][id.get(b)] = values[idx];
    ratio[id.get(b)][id.get(a)] = 1 / values[idx];
  });
  for (let k = 0; k < n; k++) {
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        if (ratio[i][j] === -1 && ratio[i][k] !== -1 && ratio[k][j] !== -1) {
          ratio[i][j] = ratio[i][k] * ratio[k][j];
        }
      }
    }
  }
  return queries.map(([a, b]) => (id.has(a) && id.has(b) ? ratio[id.get(a)][id.get(b)] : -1));
}

function maxProfit(prices) {
  let lowest = Infinity, best = 0;
  for (const p of prices) {
    if (p < lowest) lowest = p;
    else if (p - lowest > best) best = p - lowest;
  }
  return best;
}

function findMinArrowShots(points) {
  if (points.length === 0) return 0;
  const sorted = points.map(p => [p[0], p[1]]).sort((a, b) => a[1] - b[1]);
  let arrows = 1, pos = sorted[0][1];
  for (let i = 1; i < sorted.length; i++) {
