    }
    if (op === 'remove') {
      const v = args[i][0];
      if (!pos.has(v)) return false;
      const idx = pos.get(v);
      const last = items[items.length - 1];
      items[idx] = last;
      pos.set(last, idx);
      items.pop();
      pos.delete(v);
      return true;
    }
    if (op === 'getRandom') {
      return items[Math.floor(Math.random() * items.length)];
    }
    return null;
  });
}

function runTwitter(ops, args) {
  let clock = 0;
  const tweets = new Map();
