      const [u, id] = args[i];
      if (!tweets.has(u)) tweets.set(u, []);
      tweets.get(u).push([clock++, id]);
      return null;
    }
    if (op === 'follow') {
      const [a, b] = args[i];
      if (a === b) return null;
      if (!follows.has(a)) follows.set(a, new Set());
      follows.get(a).add(b);
      return null;
    }
    if (op === 'unfollow') {
      const [a, b] = args[i];
      if (follows.has(a)) follows.get(a).delete(b);
      return null;
    }
    if (op === 'getNewsFeed') {
