function findTargetSumWays(nums, target) {
    const total = nums.reduce((a, b) => a + b, 0);
    if (Math.abs(target) > total || (total + target) % 2 !== 0) return 0;
    const need = (total + target) / 2;
    const ways = new Array(need + 1).fill(0);
    ways[0] = 1;
    for (const num of nums) {
      for (let s = need; s >= num; s--) ways[s] += ways[s - num];
    }
    return ways[need];
  }

function change(amount, coins) {
    const ways = new Array(amount + 1).fill(0);
    ways[0] = 1;
    for (const c of coins) {
      for (let a = c; a <= amount; a++) ways[a] += ways[a - c];
    }
    return ways[amount];
  }

function numSquares(n) {
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 1; i <= n; i++) {
      for (let j = 1; j * j <= i; j++) dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
    }
    return dp[n];
  }

function lastStoneWeightII(stones) {
    const total = stones.reduce((a, b) => a + b, 0);
    const half = total >> 1;
    const can = new Array(half + 1).fill(false);
    can[0] = true;
    for (const w of stones) {
      for (let s = half; s >= w; s--) if (can[s - w]) can[s] = true;
    }
    for (let s = half; s >= 0; s--) if (can[s]) return total - 2 * s;
    return total;
  }

