function findMaxForm(strs, m, n) {
    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
    for (const s of strs) {
      let z = 0, o = 0;
      for (const ch of s) ch === '0' ? z++ : o++;
      for (let i = m; i >= z; i--) {
        for (let j = n; j >= o; j--) dp[i][j] = Math.max(dp[i][j], dp[i - z][j - o] + 1);
      }
    }
    return dp[m][n];
  }

function minPathSum(grid) {
    const m = grid.length, n = grid[0].length;
    const best = new Array(n).fill(Infinity);
    best[0] = 0;
    for (let r = 0; r < m; r++) {
      for (let c = 0; c < n; c++) {
        const fromLeft = c > 0 ? best[c - 1] : Infinity;
        best[c] = grid[r][c] + Math.min(best[c], fromLeft);
      }
    }
    return best[n - 1];
  }

function uniquePathsWithObstacles(obstacleGrid) {
    const m = obstacleGrid.length, n = obstacleGrid[0].length;
    const ways = new Array(n).fill(0);
    ways[0] = obstacleGrid[0][0] === 1 ? 0 : 1;
    for (let r = 0; r < m; r++) {
      for (let c = 0; c < n; c++) {
        if (obstacleGrid[r][c] === 1) ways[c] = 0;
        else if (c > 0) ways[c] += ways[c - 1];
      }
    }
    return ways[n - 1];
  }

function minimumTotal(triangle) {
    const best = [...triangle[triangle.length - 1]];
    for (let i = triangle.length - 2; i >= 0; i--) {
      for (let j = 0; j <= i; j++) best[j] = triangle[i][j] + Math.min(best[j], best[j + 1]);
    }
    return best[0];
  }

function calculateMinimumHP(dungeon) {
    const m = dungeon.length, n = dungeon[0].length;
    const need = new Array(n).fill(Infinity);
    for (let r = m - 1; r >= 0; r--) {
      for (let c = n - 1; c >= 0; c--) {
        let next;
        if (r === m - 1 && c === n - 1) next = 1;
        else next = Math.min(need[c], c + 1 < n ? need[c + 1] : Infinity);
        need[c] = Math.max(1, next - dungeon[r][c]);
      }
    }
    return need[0];
  }

function numDistinct(s, t) {
    const ways = new Array(t.length + 1).fill(0);
    ways[0] = 1;
    for (const c of s) {
      for (let j = t.length; j >= 1; j--) {
        if (c === t[j - 1]) ways[j] += ways[j - 1];
      }
    }
    return ways[t.length];
  }

