function isInterleave(s1, s2, s3) {
    const m = s1.length, n = s2.length;
    if (m + n !== s3.length) return false;
    const ok = new Array(n + 1).fill(false);
    for (let i = 0; i <= m; i++) {
      for (let j = 0; j <= n; j++) {
        if (i === 0 && j === 0) ok[j] = true;
        else {
          const fromS1 = i > 0 && ok[j] && s1[i - 1] === s3[i + j - 1];
          const fromS2 = j > 0 && ok[j - 1] && s2[j - 1] === s3[i + j - 1];
          ok[j] = fromS1 || fromS2;
        }
      }
    }
    return ok[n];
  }

function shortestCommonSupersequence(a, b) {
    const m = a.length, n = b.length;
    const len = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
    for (let i = m; i >= 0; i--) {
      for (let j = n; j >= 0; j--) {
        if (i === m) len[i][j] = n - j;
        else if (j === n) len[i][j] = m - i;
        else if (a[i] === b[j]) len[i][j] = 1 + len[i + 1][j + 1];
        else len[i][j] = 1 + Math.min(len[i + 1][j], len[i][j + 1]);
      }
    }
    let i = 0, j = 0, out = '';
    while (i < m && j < n) {
      if (a[i] === b[j]) { out += a[i]; i++; j++; }
      else if (len[i + 1][j] < len[i][j + 1]) { out += a[i]; i++; }
      else if (len[i][j + 1] < len[i + 1][j]) { out += b[j]; j++; }
      else if (a[i] < b[j]) { out += a[i]; i++; }
      else { out += b[j]; j++; }
    }
    return out + a.slice(i) + b.slice(j);
  }

function minDistance(word1, word2) {
    const m = word1.length, n = word2.length;
    let prev = new Array(n + 1).fill(0);
    for (let i = 1; i <= m; i++) {
      const cur = new Array(n + 1).fill(0);
      for (let j = 1; j <= n; j++) {
        if (word1[i - 1] === word2[j - 1]) cur[j] = prev[j - 1] + 1;
        else cur[j] = Math.max(prev[j], cur[j - 1]);
      }
      prev = cur;
    }
    return m + n - 2 * prev[n];
  }

function countSubstrings(s) {
    let count = 0;
    for (let center = 0; center < 2 * s.length - 1; center++) {
      let l = center >> 1;
      let r = l + (center & 1);
      while (l >= 0 && r < s.length && s[l] === s[r]) {
        count++;
        l--;
        r++;
      }
    }
    return count;
  }

function longestPalindromeSubseq(s) {
    const n = s.length;
    let next = new Array(n).fill(0);
    for (let i = n - 1; i >= 0; i--) {
      const cur = new Array(n).fill(0);
      cur[i] = 1;
      for (let j = i + 1; j < n; j++) {
        if (s[i] === s[j]) cur[j] = next[j - 1] + 2;
        else cur[j] = Math.max(next[j], cur[j - 1]);
      }
      next = cur;
    }
    return n === 0 ? 0 : next[n - 1];
  }

function maxCoins(nums) {
    const pad = [1, ...nums, 1];
    const n = pad.length;
    const best = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let gap = 2; gap < n; gap++) {
      for (let l = 0; l + gap < n; l++) {
        const r = l + gap;
        for (let k = l + 1; k < r; k++) {
          const coins = best[l][k] + best[k][r] + pad[l] * pad[k] * pad[r];
          if (coins > best[l][r]) best[l][r] = coins;
        }
      }
    }
    return best[0][n - 1];
  }

function mctFromLeafValues(arr) {
    const n = arr.length;
    const cost = Array.from({ length: n }, () => new Array(n).fill(0));
    const big = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) big[i][i] = arr[i];
    for (let len = 2; len <= n; len++) {
      for (let i = 0; i + len - 1 < n; i++) {
        const j = i + len - 1;
        big[i][j] = Math.max(big[i][j - 1], arr[j]);
        let best = Infinity;
        for (let k = i; k < j; k++) {
          best = Math.min(best, cost[i][k] + cost[k + 1][j] + big[i][k] * big[k + 1][j]);
        }
        cost[i][j] = best;
      }
    }
    return cost[0][n - 1];
  }

function robTree(root) {
    const val = [], left = [], right = [];
    const q = [];
    if (root.length && root[0] !== null) { val.push(root[0]); left.push(-1); right.push(-1); q.push(0); }
    let i = 1;
    for (let h = 0; h < q.length; h++) {
      const id = q[h];
      for (const side of [left, right]) {
        if (i < root.length && root[i] !== null) {
          val.push(root[i]); left.push(-1); right.push(-1);
          side[id] = val.length - 1;
          q.push(val.length - 1);
        }
        i++;
      }
    }
    const rob = new Array(val.length).fill(0), skip = new Array(val.length).fill(0);
    for (let k = q.length - 1; k >= 0; k--) {
      const id = q[k];
      let robSum = val[id], skipSum = 0;
      for (const c of [left[id], right[id]]) {
        if (c === -1) continue;
        robSum += skip[c];
        skipSum += Math.max(rob[c], skip[c]);
      }
      rob[id] = robSum;
      skip[id] = skipSum;
    }
    return val.length ? Math.max(rob[0], skip[0]) : 0;
  }

function minCameraCover(root) {
    const n = root.length;
    const kids = Array.from({ length: n }, () => [-1, -1]);
    const order = [];
    if (n && root[0] !== null) {
      const q = [0];
      let i = 1;
      for (let h = 0; h < q.length; h++) {
        const id = q[h];
        order.push(id);
        for (let side = 0; side < 2; side++) {
          if (i < n && root[i] !== null) { kids[id][side] = i; q.push(i); }
          i++;
        }
      }
    }
    const state = new Array(n).fill(2);
    let cameras = 0;
    for (let k = order.length - 1; k >= 0; k--) {
      const id = order[k];
      const s = kids[id].map(c => (c === -1 ? 2 : state[c]));
      if (s.includes(0)) { cameras++; state[id] = 1; }
      else if (s.includes(1)) state[id] = 2;
      else state[id] = 0;
    }
    if (order.length && state[0] === 0) cameras++;
    return cameras;
  }

function numTrees(n) {
    const count = new Array(n + 1).fill(0);
    count[0] = 1;
    for (let k = 1; k <= n; k++) {
      for (let root = 1; root <= k; root++) {
        count[k] += count[root - 1] * count[k - root];
      }
    }
    return count[n];
  }

function longestZigZag(root) {
    const n = root.length;
    const left = new Array(n).fill(-1), right = new Array(n).fill(-1), order = [];
    if (n && root[0] !== null) {
      const q = [0];
      let i = 1;
      for (let h = 0; h < q.length; h++) {
        const id = q[h];
        order.push(id);
        if (i < n && root[i] !== null) { left[id] = i; q.push(i); }
        i++;
        if (i < n && root[i] !== null) { right[id] = i; q.push(i); }
        i++;
      }
    }
    const goLeft = new Array(n).fill(0), goRight = new Array(n).fill(0);
    let best = 0;
    for (let k = order.length - 1; k >= 0; k--) {
      const id = order[k];
      if (left[id] !== -1) goLeft[id] = 1 + goRight[left[id]];
      if (right[id] !== -1) goRight[id] = 1 + goLeft[right[id]];
      best = Math.max(best, goLeft[id], goRight[id]);
    }
    return best;
  }

function longestIncreasingPath(matrix) {
    const m = matrix.length, n = m ? matrix[0].length : 0;
    const memo = Array.from({ length: m }, () => new Array(n).fill(0));
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    function dfs(r, c) {
      if (memo[r][c]) return memo[r][c];
      let best = 1;
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nr < m && nc >= 0 && nc < n && matrix[nr][nc] > matrix[r][c]) {
          best = Math.max(best, 1 + dfs(nr, nc));
        }
      }
      memo[r][c] = best;
      return best;
    }
    let ans = 0;
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) ans = Math.max(ans, dfs(r, c));
    return ans;
  }

function longestStrChain(words) {
    const sorted = [...words].sort((a, b) => a.length - b.length);
    const chain = new Map();
    let best = 0;
    for (const w of sorted) {
      let cur = 1;
      for (let i = 0; i < w.length; i++) {
        const prev = w.slice(0, i) + w.slice(i + 1);
        if (chain.has(prev)) cur = Math.max(cur, chain.get(prev) + 1);
      }
      chain.set(w, cur);
      best = Math.max(best, cur);
    }
    return best;
  }

function largestDivisibleSubset(nums) {
    const a = [...nums].sort((x, y) => x - y);
    const n = a.length;
    if (!n) return [];
    const size = new Array(n).fill(1), prev = new Array(n).fill(-1);
    let end = 0;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < i; j++) {
        if (a[i] % a[j] === 0 && size[j] + 1 > size[i]) {
          size[i] = size[j] + 1;
          prev[i] = j;
        }
      }
      if (size[i] > size[end]) end = i;
    }
    const out = [];
    for (let i = end; i !== -1; i = prev[i]) out.push(a[i]);
    return out.reverse();
  }

function maxSumAfterPartitioning(arr, k) {
    const n = arr.length;
    const best = new Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++) {
      let mx = 0;
      for (let len = 1; len <= Math.min(k, i); len++) {
        mx = Math.max(mx, arr[i - len]);
        best[i] = Math.max(best[i], best[i - len] + len * mx);
      }
    }
    return best[n];
  }

function shortestPathLength(n, edges) {
    if (n === 1) return 0;
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
    const full = (1 << n) - 1;
    const seen = Array.from({ length: n }, () => new Array(1 << n).fill(false));
    let queue = [];
    for (let i = 0; i < n; i++) { queue.push([i, 1 << i]); seen[i][1 << i] = true; }
    let dist = 0;
    while (queue.length) {
      const next = [];
      for (const [node, mask] of queue) {
        if (mask === full) return dist;
        for (const v of adj[node]) {
          const m2 = mask | (1 << v);
          if (!seen[v][m2]) { seen[v][m2] = true; next.push([v, m2]); }
        }
      }
      queue = next;
      dist++;
    }
    return -1;
  }

function canPartitionKSubsets(nums, k) {
    const total = nums.reduce((a, b) => a + b, 0);
    if (total % k !== 0) return false;
    const target = total / k;
    const n = nums.length;
    if (nums.some(x => x > target)) return false;
    const fill = new Array(1 << n).fill(-1);
    fill[0] = 0;
    for (let mask = 0; mask < (1 << n); mask++) {
      if (fill[mask] === -1) continue;
      for (let i = 0; i < n; i++) {
        if (mask & (1 << i)) continue;
        const next = mask | (1 << i);
        if (fill[next] === -1 && fill[mask] + nums[i] <= target) {
          fill[next] = (fill[mask] + nums[i]) % target;
        }
      }
    }
    return fill[(1 << n) - 1] === 0;
  }

function smallestSufficientTeam(reqSkills, people) {
    const bit = new Map(reqSkills.map((s, i) => [s, i]));
    const masks = people.map(p => p.reduce((m, s) => m | (1 << bit.get(s)), 0));
    const full = (1 << reqSkills.length) - 1;
    const team = new Array(full + 1).fill(null);
    team[0] = [];
    for (let p = 0; p < people.length; p++) {
      if (masks[p] === 0) continue;
      for (let mask = 0; mask <= full; mask++) {
        if (team[mask] === null) continue;
        const next = mask | masks[p];
        if (next === mask) continue;
        if (team[next] === null || team[next].length > team[mask].length + 1) {
          team[next] = [...team[mask], p];
        }
      }
    }
    return team[full];
  }

function numberWays(hats) {
    const MOD = 1000000007;
    const n = hats.length;
    const likers = Array.from({ length: 41 }, () => []);
    hats.forEach((list, person) => { for (const h of list) likers[h].push(person); });
    const full = (1 << n) - 1;
    const ways = new Array(full + 1).fill(0);
    ways[0] = 1;
    for (let h = 1; h <= 40; h++) {
      for (let mask = full; mask >= 0; mask--) {
        if (ways[mask] === 0) continue;
        for (const p of likers[h]) {
          if (mask & (1 << p)) continue;
          const next = mask | (1 << p);
          ways[next] = (ways[next] + ways[mask]) % MOD;
        }
      }
    }
    return ways[full];
  }

function runNumArray(ops, args) {
    let n = 0, nums = [], tree = [];
    function add(i, delta) {
      for (i++; i <= n; i += i & -i) tree[i] += delta;
    }
    function prefix(i) {
      let s = 0;
      for (i++; i > 0; i -= i & -i) s += tree[i];
      return s;
    }
    return ops.map((op, k) => {
      if (op === 'NumArray') {
        nums = [...args[k][0]];
        n = nums.length;
        tree = new Array(n + 1).fill(0);
        nums.forEach((v, i) => add(i, v));
        return null;
      }
      if (op === 'update') {
        const [index, val] = args[k];
        add(index, val - nums[index]);
        nums[index] = val;
        return null;
      }
      const [left, right] = args[k];
      return prefix(right) - (left > 0 ? prefix(left - 1) : 0);
    });
  }

function countSmaller(nums) {
    const sorted = [...new Set(nums)].sort((a, b) => a - b);
    const rank = new Map(sorted.map((v, i) => [v, i + 1]));
    const m = sorted.length;
    const tree = new Array(m + 1).fill(0);
    const counts = new Array(nums.length).fill(0);
    for (let i = nums.length - 1; i >= 0; i--) {
      const r = rank.get(nums[i]);
      let s = 0;
      for (let j = r - 1; j > 0; j -= j & -j) s += tree[j];
      counts[i] = s;
      for (let j = r; j <= m; j += j & -j) tree[j]++;
    }
    return counts;
  }

