solution:
function countRangeSum(nums, lower, upper) {
    const prefix = [0];
    for (const x of nums) prefix.push(prefix[prefix.length - 1] + x);
    function sortCount(lo, hi) {
      if (hi - lo <= 1) return 0;
      const mid = (lo + hi) >> 1;
      let count = sortCount(lo, mid) + sortCount(mid, hi);
      let a = mid, b = mid;
      for (let i = lo; i < mid; i++) {
        while (a < hi && prefix[a] - prefix[i] < lower) a++;
        while (b < hi && prefix[b] - prefix[i] <= upper) b++;
        count += b - a;
      }
      const merged = [];
      let p = lo, q = mid;
      while (p < mid || q < hi) {
        if (q >= hi || (p < mid && prefix[p] <= prefix[q])) merged.push(prefix[p++]);
        else merged.push(prefix[q++]);
      }
      for (let i = 0; i < merged.length; i++) prefix[lo + i] = merged[i];
      return count;
    }
    return sortCount(0, prefix.length);
  }

function fallingSquares(positions) {
    const xs = [...new Set(positions.flatMap(([left, size]) => [left, left + size]))].sort((a, b) => a - b);
    const index = new Map(xs.map((x, i) => [x, i]));
    const height = new Array(xs.length).fill(0);
    const answer = [];
    let top = 0;
    for (const [left, size] of positions) {
      const a = index.get(left), b = index.get(left + size);
      let level = 0;
      for (let i = a; i < b; i++) level = Math.max(level, height[i]);
      for (let i = a; i < b; i++) height[i] = level + size;
      top = Math.max(top, level + size);
      answer.push(top);
    }
    return answer;
  }

function getSkyline(buildings) {
    function merge(a, b) {
      const out = [];
      let i = 0, j = 0, h1 = 0, h2 = 0;
      while (i < a.length || j < b.length) {
        let x;
        if (j >= b.length || (i < a.length && a[i][0] < b[j][0])) { x = a[i][0]; h1 = a[i][1]; i++; }
        else if (i >= a.length || b[j][0] < a[i][0]) { x = b[j][0]; h2 = b[j][1]; j++; }
        else { x = a[i][0]; h1 = a[i][1]; h2 = b[j][1]; i++; j++; }
        const h = Math.max(h1, h2);
        if (!out.length || out[out.length - 1][1] !== h) out.push([x, h]);
      }
      return out;
    }
    function solve(lo, hi) {
      if (lo > hi) return [];
      if (lo === hi) { const [l, r, h] = buildings[lo]; return [[l, h], [r, 0]]; }
      const mid = (lo + hi) >> 1;
      return merge(solve(lo, mid), solve(mid + 1, hi));
    }
    return solve(0, buildings.length - 1);
  }

function findMedianSortedArrays(nums1, nums2) {
    let a = nums1, b = nums2;
    if (a.length > b.length) [a, b] = [b, a];
    const m = a.length, n = b.length;
    const half = (m + n + 1) >> 1;
    let lo = 0, hi = m;
    while (lo <= hi) {
      const i = (lo + hi) >> 1;
      const j = half - i;
      const aLeft = i > 0 ? a[i - 1] : -Infinity;
      const aRight = i < m ? a[i] : Infinity;
      const bLeft = j > 0 ? b[j - 1] : -Infinity;
      const bRight = j < n ? b[j] : Infinity;
      if (aLeft <= bRight && bLeft <= aRight) {
        if ((m + n) % 2 === 1) return Math.max(aLeft, bLeft);
        return (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2;
      }
      if (aLeft > bRight) hi = i - 1;
      else lo = i + 1;
    }
    return 0;
  }

function reversePairs(nums) {
    const a = [...nums];
    function sort(lo, hi) {
      if (hi - lo <= 1) return 0;
      const mid = (lo + hi) >> 1;
      let count = sort(lo, mid) + sort(mid, hi);
      let p = mid;
      for (let i = lo; i < mid; i++) {
        while (p < hi && a[i] > 2 * a[p]) p++;
        count += p - mid;
      }
      const merged = [];
      let l = lo, r = mid;
      while (l < mid || r < hi) {
        if (r >= hi || (l < mid && a[l] <= a[r])) merged.push(a[l++]);
        else merged.push(a[r++]);
      }
      for (let k = 0; k < merged.length; k++) a[lo + k] = merged[k];
      return count;
    }
    return sort(0, a.length);
  }

function diffWaysToCompute(expression) {
    const memo = new Map();
    function solve(s) {
      if (memo.has(s)) return memo.get(s);
      const results = [];
      for (let i = 0; i < s.length; i++) {
        const c = s[i];
        if (c !== '+' && c !== '-' && c !== '*') continue;
        const lefts = solve(s.slice(0, i));
        const rights = solve(s.slice(i + 1));
        for (const x of lefts) {
          for (const y of rights) {
            results.push(c === '+' ? x + y : c === '-' ? x - y : x * y);
          }
        }
      }
      if (results.length === 0) results.push(Number(s));
      memo.set(s, results);
      return results;
    }
    return [...solve(expression)];
  }

function carPooling(trips, capacity) {
    const events = [];
    for (const [people, from, to] of trips) {
      events.push([from, people]);
      events.push([to, -people]);
    }
    events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    let load = 0;
    for (const [, change] of events) {
      load += change;
      if (load > capacity) return false;
    }
    return true;
  }

function runMyCalendarTwo(ops, args) {
    let delta = new Map();
    return ops.map((op, i) => {
      if (op === 'MyCalendarTwo') { delta = new Map(); return null; }
      const [start, end] = args[i];
      delta.set(start, (delta.get(start) || 0) + 1);
      delta.set(end, (delta.get(end) || 0) - 1);
      let active = 0;
      for (const t of [...delta.keys()].sort((a, b) => a - b)) {
        active += delta.get(t);
        if (active >= 3) {
          delta.set(start, delta.get(start) - 1);
          delta.set(end, delta.get(end) + 1);
          return false;
        }
      }
      return true;
    });
  }

function corpFlightBookings(bookings, n) {
    const diff = new Array(n + 2).fill(0);
    for (const [first, last, seats] of bookings) {
      diff[first] += seats;
      diff[last + 1] -= seats;
    }
    const answer = [];
    let running = 0;
    for (let i = 1; i <= n; i++) {
      running += diff[i];
      answer.push(running);
    }
    return answer;
  }

function rectangleArea(rectangles) {
    const MOD = 1000000007n;
    const xs = [...new Set(rectangles.flatMap(r => [r[0], r[2]]))].sort((a, b) => a - b);
    let total = 0n;
    for (let k = 0; k + 1 < xs.length; k++) {
      const left = xs[k], right = xs[k + 1];
      const spans = rectangles
        .filter(r => r[0] <= left && r[2] >= right)
        .map(r => [r[1], r[3]])
        .sort((a, b) => a[0] - b[0]);
      let covered = 0, end = -Infinity;
      for (const [lo, hi] of spans) {
        if (lo > end) { covered += hi - lo; end = hi; }
        else if (hi > end) { covered += hi - end; end = hi; }
      }
      total += BigInt(covered) * BigInt(right - left);
    }
    return Number(total % MOD);
  }

function canAttendMeetings(intervals) {
    const sorted = [...intervals].sort((a, b) => a[0] - b[0]);
    for (let i = 1; i < sorted.length; i++) {
      if (sorted[i][0] < sorted[i - 1][1]) return false;
    }
    return true;
  }

function intervalIntersection(firstList, secondList) {
    const out = [];
    let i = 0, j = 0;
    while (i < firstList.length && j < secondList.length) {
      const start = Math.max(firstList[i][0], secondList[j][0]);
      const end = Math.min(firstList[i][1], secondList[j][1]);
      if (start <= end) out.push([start, end]);
      if (firstList[i][1] < secondList[j][1]) i++;
      else j++;
    }
    return out;
  }

function removeCoveredIntervals(intervals) {
    const sorted = [...intervals].sort((a, b) => a[0] - b[0] || b[1] - a[1]);
    let remaining = 0, maxEnd = -Infinity;
    for (const [, end] of sorted) {
      if (end > maxEnd) {
        remaining++;
        maxEnd = end;
      }
    }
    return remaining;
  }

function employeeFreeTime(schedule) {
    const all = schedule.flat().sort((a, b) => a[0] - b[0]);
    const free = [];
    let end = all.length ? all[0][1] : 0;
    for (let i = 1; i < all.length; i++) {
      const [start, stop] = all[i];
      if (start > end) free.push([end, start]);
      end = Math.max(end, stop);
    }
    return free;
  }

function countPrimes(n) {
    if (n < 3) return 0;
    const composite = new Uint8Array(n);
    let count = 0;
    for (let i = 2; i < n; i++) {
      if (composite[i]) continue;
      count++;
      for (let j = i * i; j < n; j += i) composite[j] = 1;
    }
    return count;
  }

function nthUglyNumber(n) {
    const u = [1];
    let i2 = 0, i3 = 0, i5 = 0;
    while (u.length < n) {
      const a = u[i2] * 2, b = u[i3] * 3, c = u[i5] * 5;
      const next = Math.min(a, b, c);
      u.push(next);
      if (next === a) i2++;
      if (next === b) i3++;
      if (next === c) i5++;
    }
    return u[n - 1];
  }

function fractionToDecimal(numerator, denominator) {
    if (numerator === 0) return '0';
    const negative = (numerator < 0) !== (denominator < 0);
    const num = Math.abs(numerator), den = Math.abs(denominator);
    let out = (negative ? '-' : '') + Math.floor(num / den);
    let rem = num % den;
    if (rem === 0) return out;
    out += '.';
    const seen = new Map();
    while (rem !== 0) {
      if (seen.has(rem)) {
        const at = seen.get(rem);
        return out.slice(0, at) + '(' + out.slice(at) + ')';
      }
      seen.set(rem, out.length);
      rem *= 10;
      out += Math.floor(rem / den);
      rem %= den;
    }
    return out;
  }

function convertToTitle(columnNumber) {
    let n = columnNumber;
    let title = '';
    while (n > 0) {
      n -= 1;
      title = String.fromCharCode(65 + (n % 26)) + title;
      n = Math.floor(n / 26);
    }
    return title;
  }

function isRobotBounded(instructions) {
    const dx = [0, 1, 0, -1], dy = [1, 0, -1, 0];
    let x = 0, y = 0, dir = 0;
    for (const c of instructions) {
      if (c === 'G') { x += dx[dir]; y += dy[dir]; }
      else if (c === 'L') dir = (dir + 3) % 4;
      else dir = (dir + 1) % 4;
    }
    return (x === 0 && y === 0) || dir !== 0;
  }

function convert(s, numRows) {
    if (numRows === 1 || numRows >= s.length) return s;
    const rows = Array.from({ length: numRows }, () => []);
    let row = 0, step = 1;
    for (const c of s) {
      rows[row].push(c);
      if (row === 0) step = 1;
      else if (row === numRows - 1) step = -1;
      row += step;
    }
    return rows.map(r => r.join('')).join('');
  }

function fullJustify(words, maxWidth) {
    const lines = [];
    let i = 0;
    while (i < words.length) {
      let j = i, letters = 0;
      while (j < words.length && letters + words[j].length + (j - i) <= maxWidth) {
        letters += words[j].length;
        j++;
      }
      const gaps = j - i - 1;
      let line = '';
      if (j === words.length || gaps === 0) {
        line = words.slice(i, j).join(' ');
        line += ' '.repeat(maxWidth - line.length);
      } else {
        const spaces = maxWidth - letters;
        const base = Math.floor(spaces / gaps), extra = spaces % gaps;
        for (let k = i; k < j; k++) {
          line += words[k];
          if (k < j - 1) line += ' '.repeat(base + (k - i < extra ? 1 : 0));
        }
      }
      lines.push(line);
      i = j;
    }
    return lines;
  }

function intToRoman(num) {
    const values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
    const symbols = ['M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I'];
    let out = '';
    for (let i = 0; i < values.length; i++) {
      while (num >= values[i]) {
        out += symbols[i];
        num -= values[i];
      }
    }
    return out;
  }

function containsDuplicate(nums) {
    const seen = new Set();
    for (const x of nums) {
      if (seen.has(x)) return true;
      seen.add(x);
    }
    return false;
  }

function isAnagram(s, t) {
    if (s.length !== t.length) return false;
    const counts = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
      counts[s.charCodeAt(i) - 97]++;
      counts[t.charCodeAt(i) - 97]--;
    }
    return counts.every(c => c === 0);
  }

function codec(strs) {
    function encode(list) {
      return list.map(s => s.length + '#' + s).join('');
    }
    function decode(text) {
      const out = [];
      let i = 0;
      while (i < text.length) {
        const hash = text.indexOf('#', i);
        const len = Number(text.slice(i, hash));
        out.push(text.slice(hash + 1, hash + 1 + len));
        i = hash + 1 + len;
      }
      return out;
    }
    return decode(encode(strs));
  }

function missingNumber(nums) {
    const n = nums.length;
    let expected = (n * (n + 1)) / 2;
    for (const x of nums) expected -= x;
    return expected;
  }
